mapper.select:
SELECT IFNULL(SUM(CASE WHEN USER_PWD = #{userPwd} THEN 1 ELSE 0 END), 0) AS CNT FROM ( SELECT USER_PWD FROM ( SELECT USER_PWD , CHNG_TMSP FROM ADM_USER_PWD_CHNG_TXN WHERE USER_ID = #{userId}
UNION ALL
SELECT USER_PWD , IFNULL(LAST_CHNG_TMSP, FRST_REGI_TMSP) AS FRST_REGI_TMSP FROM ADM_USER_BAS WHERE USER_ID = #{userId} AND IFNULL(ADM_USER_STUS_CD,'') != #{admUserStusCd} /* 비밀번호 초기화의 경우, 체크 대상에서 제외 */ ) S ORDER BY CHNG_TMSP DESC ) T LIMIT 0, 5

